Arguments:
(new MultiSelectionInquiryData(
                T("BC_Lordship_GrantTitle", "Grant {LORDSHIP_TYPE}", village), description.ToString(), choices, true, 1, 1,
                T("BC_Hierarchy_ActionGrant", "Grant"), T("BC_UI_Cancel", "Cancel"), selected =>
                {
                    Hero hero = selected?.FirstOrDefault()?.Identifier as Hero;
                    if (hero == null) return;
                    if (!behavior.TryGrantFromPlayerHouse(village, hero, out var reason)) Failure(reason);
                    else changed?.Invoke();
                }, null), true)

(new MultiSelectionInquiryData(
                T("BC_Lordship_GrantTitle", "Grant {LORDSHIP_TYPE}"), description.ToString(), choices, true, 1, 1,
                T("BC_Hierarchy_ActionGrant", "Grant"), T("BC_UI_Cancel", "Cancel"), selected =>
                {
                    var village = selected?.FirstOrDefault()?.Identifier as Settlement;
                    if (village == null) return;
                    if (!behavior.TryGrant(Clan.PlayerClan, village, hero, out var reason)) Failure(reason);
                    else changed?.Invoke();
                }, null), true)

(new InquiryData(T("BC_Lordship_RevokeTitle", "Revoke {LORDSHIP_TYPE}", village), body.ToString(),
                true, true, T("BC_Hierarchy_ActionRevoke", "Revoke"), T("BC_UI_Cancel", "Cancel"), () =>
                {
                    if (LordshipBehavior.Instance?.TryRevoke(Clan.PlayerClan, village, out var reason) == true) changed?.Invoke();
                    else Failure(LordshipBehavior.Text("BC_Lordship_Changed", "This grant is no longer available."));
                }, null), true)

(
                new InquiryData(
                    title.ToString(),
                    description.ToString(),
                    true,
                    true,
                    joinText.ToString(),
                    new TextObject("{=BC_CivilWar_PlayerCall_Crown}Stand with the Crown").ToString(),
                    () =>
                    {
                        CivilWarSolidarityHelper.JoinPlayerRebellion(rebelFaction, context);
                        TextObject msg = new TextObject("{=BC_CivilWar_PlayerCall_JoinedMsg}You answer {LIEGE_NAME}'s summons. Your banners now fly with the rebellion against the crown.");
                        msg.SetTextVariable("LIEGE_NAME", sponsor.Name);
                        BellumCivileNotifications.ShowPersonal(msg, BellumNotificationColors.Rebellion);
                    },
                    () =>
                    {
                        CivilWarSolidarityHelper.KeepPlayerLoyal(rebelFaction, context);
                        TextObject msg = new TextObject("{=BC_CivilWar_PlayerCall_LoyalMsg}You refuse {LIEGE_NAME}'s summons and stand with the crown. Your choice will not soon be forgotten.");
                        msg.SetTextVariable("LIEGE_NAME", sponsor.Name);
                        BellumCivileNotifications.ShowPersonal(msg, BellumNotificationColors.Success);
                    }),
                true)

(new MultiSelectionInquiryData(
                new TextObject("{=BC_VoluntaryPact_OfferHostageTitle}Offer a Hostage").ToString(),
                new TextObject("{=BC_VoluntaryPact_OfferHostageBody}Choose a relative of your ruling house to offer as a pledge of peace.").ToString(),
                options, true, 1, 1, new TextObject("{=BC_VoluntaryPact_Next}Next").ToString(),
                new TextObject("{=BC_VoluntaryPact_Cancel}Cancel").ToString(), selected =>
                {
                    if (selected?.Count == 1 && selected[0].Identifier is Hero hostage)
                        AskDuration(owner, source, target, hostage, resolve);
                }, null), true)

(new InquiryData(new TextObject("{=BC_VoluntaryPact_ConfirmTitle}Propose a Pledge").ToString(),
                body.ToString(), true, true, new TextObject("{=BC_VoluntaryPact_Submit}Propose").ToString(),
                new TextObject("{=BC_VoluntaryPact_Cancel}Cancel").ToString(), () =>
                {
                    if (!owner.CanPropose(source, target, Clan.PlayerClan, out var failure)) { ShowFailure(failure); return; }
                    if (!owner.TryCreateAndFile(source, target, Clan.PlayerClan, hostage, days, payment, out string id))
                    { ShowFailure(null); return; }
                    var decision = owner.Find(id)?.SourceDecision;
                    if (decision != null && decision.Kingdom?.UnresolvedDecisions?.Contains(decision) == true) resolve?.Invoke(decision);
                }, null))

(new InquiryData(
                GameTexts.FindText("str_abdicate_leadership").ToString(), behavior.DescribeAbdication(preview).ToString(),
                true, true, GameTexts.FindText("str_yes").ToString(), GameTexts.FindText("str_no").ToString(),
                () =>
                {
                    if (!behavior.ConfirmAbdication(preview, out var result))
                    {
                        BellumCivileNotifications.ShowPersonal(result, BellumNotificationColors.Warning);
                        __instance.OnRefresh();
                        return;
                    }
                    if (!preview.Completed && !preview.Emergency)
                        BellumCivileNotifications.ShowPersonal(result, BellumNotificationColors.Warning);
                    // Do not force an unrelated filed motion or native abdication vote.
                    AccessTools.Method(typeof(KingdomManagementVM), "ExecuteClose").Invoke(__instance, null);
                }, null), true)

(
                    new InquiryData(
                        new TextObject("{=BC_PlayerRegency_ConfirmTitle}Regency").ToString(),
                        regencyDescription.ToString(),
                        true,
                        true,
                        new TextObject("{=BC_PlayerRegency_Confirm}Confirm").ToString(),
                        new TextObject("{=BC_PlayerSuccession_Cancel}Cancel").ToString(),
                        () =>
                        {
                            if (!regency.TryApprovePreparedPlayerSuccessor(successorToFinalize))
                                return;

                            try
                            {
                                FinalizeMethod.Invoke(__instance, new object[] { successorToFinalize });
                            }
                            catch (Exception ex)
                            {
                                regency.CancelPreparedPlayerSuccessorApproval(successorToFinalize);
                                BellumCivileLogger.Log(
                                    $"Could not finalize player regency selection; successor={successorToFinalize.StringId}; error={ex.GetType().Name}:{ex.Message}.");
                            }
                        },
                        null),
                    true)

(new InquiryData(notice.Title, notice.Body, true, false,
                new TextObject("{=BC_Result_Continue}Continue").ToString(), "", () =>
                {
                    notice.Acknowledged = true;
                    if (_pending.Count > 0 && _pending.Peek() == notice) _pending.Dequeue();
                    _active = null;
                }, null), true)

(new MultiSelectionInquiryData(
                    new TextObject("{=BC_CourtDynasticTitle}A Bond Between Crowns").ToString(),
                    DynasticText(a, new TextObject("{=BC_CourtDynasticApproach}The lords of the {FACTION} urge you to strengthen ties with {TARGET} through a marriage between {FIRST} and {SECOND}. They believe this union would serve both houses and will lend their voices to an alliance with that realm during this term.\n\nThe couple would make their household with {HOUSE}. Shall we approach {RULER} with this proposal?")).ToString(),
                    options.ToList(), false, 1, 1, new TextObject("{=BC_CourtConfirmAgenda}Confirm").ToString(), null,
                    selected => {
                        if (_activePlayerInquiry != a) return;
                        _activePlayerInquiry = null;
                        if (!PlayerDynasticAgenda(a) || a.Dynastic != plan || plan.Response != response || selected?.Count != 1) return;
                        int choice = (int)selected[0].Identifier;
                        plan.Response = choice == 0 ? CourtDynasticResponse.Approaching : choice == 1 ? CourtDynasticResponse.Deferred : CourtDynasticResponse.Declined;
                        if (choice == 0) plan.ReplyDay = CampaignTime.Now.ToDays + 1;
                    }, null), true)

(new InquiryData(new TextObject("{=BC_CourtDynasticReplyTitle}An Answer to Your Proposal").ToString(),
                    DynasticText(a, new TextObject("{=BC_CourtDynasticReply}{RULER} has answered your approach favorably and is willing to agree to the marriage of {FIRST} and {SECOND}. The couple would join {HOUSE}; no marriage payment is requested in this offer.\n\nYou may review the formal marriage offer before giving your final consent. An alliance between the realms remains a separate decision.")).ToString(),
                    true, true, new TextObject("{=BC_CourtDynasticReviewOffer}Review the marriage offer").ToString(),
                    new TextObject("{=BC_CourtDynasticDecline}I will not pursue this match.").ToString(), () => {
                        if (_activePlayerInquiry != a) return;
                        _activePlayerInquiry = null;
                        if (!PlayerDynasticAgenda(a) || a.Dynastic != plan || plan.Response != response) return;
                        if (!BellumMarriageStrategyHelper.CourtMarriageParticipant(plan.First)
                            || !BellumMarriageStrategyHelper.CourtMarriageParticipant(plan.Second)) return;
                        var match = BellumMarriageStrategyHelper.EvaluateCourtMarriage(plan.First, plan.Second, true, plan.Destination);
                        if (match == null)
                        {
                            plan.Response = CourtDynasticResponse.ForeignRefused;
                            ReportDynastic(a, new TextObject("{=BC_CourtDynasticRefused}{RULER} has declined the proposed match between {FIRST} and {SECOND}. The hoped-for union has not been agreed."));
                            return;
                        }
                        // Seal before the native offer publishes notifications or callbacks.
                        plan.Response = CourtDynasticResponse.OfferIssued;
                        if (service?.TrySendCourtMarriageOffer(match) != true) plan.Response = CourtDynasticResponse.ReplyReady;
                    }, () => {
                        if (_activePlayerInquiry != a) return;
                        _activePlayerInquiry = null;
                        if (PlayerDynasticAgenda(a) && a.Dynastic == plan && plan.Response == response) plan.Response = CourtDynasticResponse.Declined;
                    }), true)

(new InquiryData(NominationLabel(kind).ToString(), body.ToString(), true, true,
                new TextObject("{=BC_CourtConfirmAgenda}Confirm").ToString(), new TextObject("{=BC_CourtPickerBack}Back").ToString(), () =>
                {
                    if (_activePlayerInquiry != agenda) return;
                    _activePlayerInquiry = null;
                    if (!CanChooseTermBusiness(agenda) || agenda.ObjectiveData != identity || agenda.State != state
                        || crisis != agenda.CrisisInterventionPending || price != ReplacementCost(agenda, crisis)
                        || !deadline.IsFuture || !AvailablePlayerMotions(agenda, kind).Any()) return;
                    if (price > 0 && !NpcInfluenceBudgetService.TrySpend(Clan.PlayerClan, price,
                        crisis ? NpcInfluenceExpenseKind.CrownEmergency : NpcInfluenceExpenseKind.Discretionary, "court_term_substitute")) return;
                    bool overruledCrisis = crisis && CourtChallengeGraceBlock(agenda) == null;
                    // A fresh record releases all previous objective-specific reservations and effects.
                    var mandate = new CourtAgendaRecord { Realm = agenda.Realm, Faction = agenda.Faction, Sponsor = Clan.PlayerClan,
                        State = CourtAgendaState.AwaitingNomination, NominationKind = kind, NominationDeadline = deadline,
                        NominationWindowDays = agenda.NominationWindowDays, SessionDate = agenda.SessionDate, VoteDate = agenda.VoteDate,
                        HasScheduleSnapshot = agenda.HasScheduleSnapshot, TermDays = agenda.TermDays, PlayerSelectionConfirmed = true,
                        SubstitutionInfluencePaid = price, OrdinaryCrisisRestrained = agenda.OrdinaryCrisisRestrained || overruledCrisis,
                        ObjectiveData = new CourtObjectiveRecord { Kind = "policy" } };
                    if (identity.HasTermSnapshot) mandate.ObjectiveData.FreezeTerm(identity.SelectedDay, identity.DeadlineDay);
                    _agendas[_agendas.IndexOf(agenda)] = mandate;
                    if (overruledCrisis) ApplyMemberMemory(mandate, BellumCivileConstants.CourtAgendaDeclineRelationPenalty,
                        RelationMemorySources.OverruledMyFaction, 7f);
                    NotifyAgenda(mandate);
                    BellumCivileNotifications.ShowPersonal(new TextObject("{=BC_NominationGranted}The {FACTION} entrusts you with a mandate: {MOTION}. Your peers expect a proposal before {DATE}.")
                        .SetTextVariable("FACTION", AgendaOwnerName(mandate)).SetTextVariable("MOTION", NominationLabel(kind))
                        .SetTextVariable("DATE", deadline.ToString()), BellumNotificationColors.Politics);
                }, () => ReturnFromMotionPicker(agenda, identity, state, crisis, category)), true)

(new MultiSelectionInquiryData(NominationLabel(CourtCouncilObjectiveSource.CouncilKind).ToString(),
                reason.ToString(), choices, true, 1, 1,
                new TextObject("{=BC_CourtConfirmAgenda}Confirm").ToString(), new TextObject("{=BC_CourtAgenda_SubCancel}Cancel").ToString(),
                selected =>
                {
                    if (selected?.Count == 1 && !FileMandateMotion(mandate, (PlayerMotion)selected[0].Identifier))
                        BellumCivileNotifications.ShowPersonal(new TextObject("{=BC_NominationNotFiled}The proposal could not be placed before the court. If your mandate remains valid, you may choose another proposal before its deadline."), BellumNotificationColors.Warning);
                    refresh?.Invoke();
                }, _ => refresh?.Invoke()), true)

(new MultiSelectionInquiryData(
                new TextObject("{=BC_CrownActions}Crown Actions").ToString(), CrownActionsHint(realm).ToString(), choices,
                true, 1, 1, new TextObject("{=BC_CrownActionSelect}Select").ToString(), new TextObject("{=BC_CourtAgenda_SubCancel}Cancel").ToString(),
                selected => { if (selected?.Count == 1 && CanUseCrownActions(realm))
                    if ((string)selected[0].Identifier == CourtRoyalPeaceRules.Kind) ShowPlayerRoyalPeace(realm, refresh);
                    else if ((string)selected[0].Identifier == CourtClientGrantRules.Kind) ShowClientGrantFiefs(realm, refresh);
                    else ShowPlayerCrownTargets(realm, (string)selected[0].Identifier, null, refresh); }, null), true)

(new MultiSelectionInquiryData(
                new TextObject("{=BC_CrownActionClientGrant}Grant land to a client state").ToString(),
                new TextObject("{=BC_ClientGrantChooseFief}Which holding will you bestow upon a client realm?").ToString(), choices,
                true, 1, 1, new TextObject("{=BC_CourtPickerContinue}Continue").ToString(), new TextObject("{=BC_CourtAgenda_SubCancel}Cancel").ToString(),
                selected => { if (selected?.Count != 1 || !CanUseCrownActions(realm)) return;
                    string id = (string)selected[0].Identifier;
                    if (id == "back") ShowCrownActions(realm, refresh);
                    else ShowPlayerCrownTargets(realm, CourtClientGrantRules.Kind, id, refresh); }, null), true)

(new MultiSelectionInquiryData(
                new TextObject("{=BC_CrownActions}Crown Actions").ToString(),
                new TextObject("{=BC_CrownActionTarget}Whom will you name in this royal undertaking?").ToString(), choices,
                true, 1, 1, new TextObject("{=BC_CourtPickerReview}Review motion").ToString(), new TextObject("{=BC_CourtAgenda_SubCancel}Cancel").ToString(),
                selected => { if (selected?.Count != 1) return;
                    if (kind == CourtClientGrantRules.Kind && selected[0].Identifier is string) ShowClientGrantFiefs(realm, refresh);
                    else ConfirmPlayerCrownBusiness(realm, (PlayerMotion)selected[0].Identifier, refresh); }, null), true)

(new InquiryData(motion.Label.ToString(), body.ToString(), true, true,
                new TextObject("{=BC_CourtConfirmAgenda}Confirm").ToString(), new TextObject(motion.Kind == CourtClientGrantRules.Kind
                    ? "{=BC_CourtPickerBack}Back" : "{=BC_CourtAgenda_SubCancel}Cancel").ToString(),
                () => {
                    if (realm.Leader != ruler || !FilePlayerCrownBusiness(realm, motion))
                        BellumCivileNotifications.ShowPersonal(new TextObject("{=BC_CrownActionChanged}This undertaking can no longer proceed. Its conditions or cost have changed."), BellumNotificationColors.Warning);
                    refresh?.Invoke();
                }, motion.Kind == CourtClientGrantRules.Kind
                    ? (Action)(() => ShowPlayerCrownTargets(realm, motion.Kind, motion.Candidate.TargetId, refresh)) : null), true)

(new MultiSelectionInquiryData(
                new TextObject(crown ? "{=BC_CrownName}Crown" : "{=BC_CourtAgenda_Title}Faction Council").ToString(), body.ToString(), choices,
                false, 1, 1, new TextObject("{=BC_CourtConfirmAgenda}Confirm").ToString(), null,
                selected =>
                {
                    if (_activePlayerInquiry != agenda) return;
                    _activePlayerInquiry = null;
                    if (!CanChooseTermBusiness(agenda) || agenda.ObjectiveData != identity || agenda.State != originalState
                        || crisis != agenda.CrisisInterventionPending || ReplacementCost(agenda, crisis) != price || selected?.Count != 1) return;
                    ApplyPlayerAgendaChoice(agenda, (int)selected[0].Identifier, crisis);
                }, null), true)

(new MultiSelectionInquiryData(
                new TextObject(agenda.Faction == null ? "{=BC_CrownChooseBusiness}Choose Crown business" : "{=BC_CourtAgenda_SubTitle}Substitute Motion").ToString(),
                new TextObject(motions.Count == 0 ? "{=BC_CourtAgenda_NoSubstitutes}No valid substitute motions are available."
                    : agenda.Faction == null ? "{=BC_CrownBusinessPrompt}Which business will you pursue in the name of the Crown?"
                    : "{=BC_CourtAgenda_SubDesc}Which motion will you force onto the {FACTION_NAME}'s agenda?")
                    .SetTextVariable("FACTION_NAME", AgendaOwnerName(agenda)).ToString(), choices, true, 1, 1,
                new TextObject("{=BC_CourtPickerContinue}Continue").ToString(), new TextObject("{=BC_CourtPickerBack}Back").ToString(),
                selected =>
                {
                    if (_activePlayerInquiry != agenda) return;
                    if (selected?.Count == 1 && ReferenceEquals(selected[0].Identifier, MotionPickerBack))
                    { ReturnFromMotionPicker(agenda, identity, state, crisis, null, category == null); return; }
                    _activePlayerInquiry = null;
                    if (!CanChooseTermBusiness(agenda) || identity != agenda.ObjectiveData || state != agenda.State
                        || crisis != agenda.CrisisInterventionPending || selected?.Count != 1) return;
                    if (categories && selected[0].Identifier is string selectedCategory)
                    { ShowTermMotionPicker(agenda, crisis, selectedCategory); return; }
                    ShowPlayerMotionConfirmation(agenda, (PlayerMotion)selected[0].Identifier, crisis, price, category);
                }, _ => ReturnFromMotionPicker(agenda, identity, state, crisis, null, category == null)), true)

(new InquiryData(motion.Label.ToString(), body.ToString(), true, true,
                new TextObject("{=BC_CourtConfirmAgenda}Confirm").ToString(), new TextObject("{=BC_CourtPickerBack}Back").ToString(), () =>
                {
                    if (_activePlayerInquiry != agenda) return;
                    _activePlayerInquiry = null;
                    if (!CanChooseTermBusiness(agenda) || !agenda.SessionDate.IsFuture || agenda.ObjectiveData != identity || agenda.State != state
                        || agenda.CrisisInterventionPending != crisis || ReplacementCost(agenda, crisis) != price) return;
                    var currentGrace = PlayerMotionGraceBlock(agenda, motion);
                    if (currentGrace != null)
                    {
                        BellumCivileNotifications.ShowPersonal(currentGrace, BellumNotificationColors.Warning);
                        return;
                    }
                    var current = AvailablePlayerMotions(agenda).FirstOrDefault(m => SamePlayerMotion(m, motion));
                    if (current == null || current.FilingCost != motion.FilingCost) return;
                    // Prepare without mutating the live agenda or charging for a cancelled preview.
                    var prepared = new CourtAgendaRecord { Realm = agenda.Realm, Sponsor = agenda.Sponsor, Faction = agenda.Faction,
                        SessionDate = agenda.SessionDate, VoteDate = agenda.VoteDate, TermDays = agenda.TermDays, HasScheduleSnapshot = agenda.HasScheduleSnapshot,
                        ObjectiveData = new CourtObjectiveRecord { Kind = "policy" } };
                    if (identity.HasTermSnapshot) prepared.ObjectiveData.FreezeTerm(identity.SelectedDay, identity.DeadlineDay);
                    if (motion.Kind != DebateKind)
                        ((ICourtAgendaObjectiveSource)_objectiveSelector.FindSource(motion.Kind)).ApplySelection(prepared,
                            new CourtObjectiveChoice(motion.Kind, motion.Candidate, new CourtObjectiveEvaluation(true, true, new CourtObjectiveWeight(1), "player_selection")));
                    if (motion.Kind == CourtActivityRules.Kind && prepared.Activity == null) return;
                    agenda.PlayerSelectionConfirmed = true;
                    if (price > 0 && !NpcInfluenceBudgetService.TrySpend(Clan.PlayerClan, price,
                        crisis ? NpcInfluenceExpenseKind.CrownEmergency : NpcInfluenceExpenseKind.Discretionary, "court_term_substitute"))
                    { agenda.PlayerSelectionConfirmed = false; return; }
                    agenda.SubstitutionInfluencePaid = price;
                    agenda.ObjectiveData = prepared.ObjectiveData;
                    agenda.PolicyId = prepared.PolicyId;
                    agenda.Abolish = prepared.Abolish;
                    agenda.HasPolicyStanceSnapshot = prepared.HasPolicyStanceSnapshot;
                    agenda.SelectedPolicyStance = prepared.SelectedPolicyStance;
                    agenda.Activity = prepared.Activity;
                    agenda.Appeasement = prepared.Appeasement;
                    agenda.Peace = prepared.Peace;
                    agenda.Campaign = prepared.Campaign;
                    agenda.Subjugation = prepared.Subjugation;
                    agenda.Claim = prepared.Claim;
                    agenda.Dynastic = prepared.Dynastic;
                    agenda.Trade = prepared.Trade;
                    agenda.TitleGrant = prepared.TitleGrant;
                    agenda.Rally = prepared.Rally;
                    agenda.Mandate = prepared.Mandate;
                    agenda.Liberation = prepared.Liberation;
                    agenda.Protection = prepared.Protection;
                    agenda.SessionDate = prepared.SessionDate;
                    agenda.OriginalHolder = prepared.OriginalHolder;
                    agenda.PreferredCouncilCandidate = prepared.PreferredCouncilCandidate;
                    agenda.CouncilMotionId = prepared.CouncilMotionId;
                    agenda.CrisisInterventionPending = false;
                    bool overruledCrisis = crisis && CourtChallengeGraceBlock(agenda) == null;
                    agenda.OrdinaryCrisisRestrained |= overruledCrisis;
                    agenda.State = motion.Kind == DebateKind ? CourtAgendaState.Crisis : CourtAgendaState.Announced;
                    if (overruledCrisis) ApplyMemberMemory(agenda, BellumCivileConstants.CourtAgendaDeclineRelationPenalty,
                        RelationMemorySources.OverruledMyFaction, 7f);
                    BellumCivileLogger.Log($"Court player selection; realm={agenda.Realm.StringId}; owner={agenda.Faction?.Type.ToString() ?? "Crown"}; kind={motion.Kind}; target={motion.Candidate.TargetId}; selection_cost={price}; session={agenda.SessionDate.ToDays}.");
                    NotifyAgenda(agenda);
                }, () => ReturnFromMotionPicker(agenda, identity, state, crisis, category)), true)

(new InquiryData(new TextObject("{=BC_RoyalPeace_ConfirmTitle}Enforce Peace").ToString(),
                description.ToString(), true, true, new TextObject("{=BC_RoyalPeaceAnnounce}Announce Decree").ToString(),
                new TextObject("{=BC_UI_Cancel}Cancel").ToString(), () => {
                    if (!CanUseCrownActions(realm) || realm.Leader != ruler) return;
                    var current = RoyalExecutor?.GetRealmPreview(realm, Clan.PlayerClan);
                    string report = null;
                    if (current?.IsEnabled != true
                        || !CourtRoyalPeaceRules.QuoteStillValid(preview.Wartime, preview.InfluenceCost, current.Wartime, current.InfluenceCost)
                        || !TryScheduleRoyalPeace(realm, Clan.PlayerClan, out report))
                        BellumCivileNotifications.ShowPersonal(new TextObject("{=BC_CrownActionChanged}This undertaking can no longer proceed. Its conditions or cost have changed."), BellumNotificationColors.Warning);
                    refresh?.Invoke();
                }, null), true)

(new InquiryData(new TextObject("{=BC_ProtectionTitle}A Crown Under Protection").ToString(), text.ToString(), true, true,
                new TextObject(sender ? "{=BC_ProtectionSend}Send the appeal" : "{=BC_ProtectionAccept}Accept their submission and defend them").ToString(),
                new TextObject("{=BC_ProtectionReject}Decline the proposal").ToString(), () =>
                {
                    if (!ValidProtectionCallback(p, phase)) return;
                    _activeProtectionInquiry = null;
                    if (sender) SendProtection(p); else AcceptProtection(p);
                }, () =>
                {
                    if (!ValidProtectionCallback(p, phase)) return;
                    _activeProtectionInquiry = null;
                    CloseProtection(p, CourtProtectionPhase.Declined, sender ? "player_withheld_appeal" : "player_declined_protection");
                }), true)

(new MultiSelectionInquiryData(new TextObject("{=BC_TitleGrantInquiryTitle}A Petition for Royal Favor").ToString(),
                body.ToString(), choices, false, 1, 1, new TextObject("{=BC_TitleGrantConfirm}Confirm response").ToString(), null, selected =>
                {
                    if (_activePlayerInquiry != a) return;
                    _activePlayerInquiry = null;
                    if (!_agendas.Contains(a) || !PlayerTitlePetition(a) || a.TitleGrant != p || p.Response != CourtTitleResponse.AwaitingPlayer || !GrantUnchanged(p)) return;
                    if (selected == null || selected.Count != 1) return;
                    string answer = selected[0]?.Identifier as string;
                    if (answer == "grant")
                    {
                        if (!NpcInfluenceBudgetService.CanAfford(p.Grantor, FeudalTitlePlayerActionService.GrantInfluenceCost, NpcInfluenceExpenseKind.Discretionary)) return;
                        AcceptTitleGrant(a);
                    }
                    else p.Response = answer == "refuse" ? CourtTitleResponse.Refused : CourtTitleResponse.Deferred;
                }, null), true)

(new MultiSelectionInquiryData(
                ContestText("{=BC_Contest_Title}A Disputed Election"), string.Join("\n\n", lines), choices, false, 1, 1,
                ContestText("{=BC_Contest_Answer}Give your answer"), "", selected =>
                {
                    _inquiry = null;
                    var chosen = selected?.FirstOrDefault()?.Identifier as Hero;
                    if (chosen == null) return;
                    if (!AnswerUltimata(record, chosen == record.ElectedWinner ? null : chosen))
                        InformationManager.DisplayMessage(new InformationMessage(ContestText("{=BC_Contest_ResponseChanged}The circumstances have changed. Your answer could not be delivered.")));
                }, null), true)

(new MultiSelectionInquiryData(
                new TextObject("{=BC_Fabrication_SetbackTitle}A Letter from Your Scribe").ToString(), body.ToString(),
                choices, false, 1, 1, new TextObject("{=BC_Fabrication_SetbackConfirm}Send instructions").ToString(), null,
                selected => {
                    _isShowingPlayerOutcome = false;
                    if (selected?.Count == 1) ResolveSetbackChoice(record, stage, (int)selected[0].Identifier);
                }, null), true)

(new InquiryData(
                new TextObject("{=BC_Parley_ForcedSurrenderTitle}Unconditional Surrender").ToString(),
                body.ToString(),
                true,
                false,
                new TextObject("{=BC_Parley_ReviewTerms}Review Terms").ToString(),
                string.Empty,
                () =>
                {
                    // Inquiry callbacks run before their Gauntlet layer is always fully dismissed. Opening
                    // another overlay here can therefore fail even though the treaty remains valid. Let the
                    // next safe campaign UI tick perform the handoff instead.
                    _pendingPlayerParleyOpenProposalId = proposal.ProposalId;
                    BellumCivileLogger.Log($"Forced player parley queued after envoy inquiry; war={proposal.WarKey}; proposal={proposal.ProposalId}.");
                },
                null), true, false)

(new MultiSelectionInquiryData(
                new TextObject("{=BC_Hostage_DispositionTitle}A Broken Pledge").ToString(), body.ToString(), elements,
                true, 1, 1, new TextObject("{=BC_Hostage_Decide}Confirm judgment").ToString(),
                new TextObject("{=BC_Hostage_Later}Decide later").ToString(), selected =>
                {
                    _hostageInquiryOpen = false;
                    if (record.ReceivingHouse?.Leader != Hero.MainHero || !InTreatyCustody(record)
                        || pact.Phase != HostagePactPhase.Resolving || selected?.Count != 1) return;
                    var choice = (HostageCustodyOutcome)selected[0].Identifier;
                    if (choice == HostageCustodyOutcome.Execute && (pact.VoluntaryAggressor == null || !ExecutionAllowed(record))) return;
                    if (record.TryChoose(choice)) record.ClemencyChosen = choice == HostageCustodyOutcome.Release;
                    MaintainCustody();
                }, _ => _hostageInquiryOpen = false), true)

(new InquiryData(
                title.ToString(),
                description.ToString(),
                true,
                hasAlternativeCandidate,
                new TextObject("{=BC_Ideology_PlayerLeader_Accept}Accept").ToString(),
                new TextObject("{=BC_Ideology_PlayerLeader_Refuse}Refuse").ToString(),
                () =>
                {
                    if (CourtMembershipEligibility.CanBelong(Clan.PlayerClan, kingdom)
                        && faction.Members?.Contains(Clan.PlayerClan) == true)
                    {
                        ApplyCourtFactionLeadershipChange(faction, kingdom, Clan.PlayerClan);
                    }
                },
                () =>
                {
                    Clan nextCandidate = GetRankedCourtFactionLeadershipCandidates(faction, kingdom)
                        .FirstOrDefault(clan => clan != Clan.PlayerClan);
                    if (nextCandidate == null)
                        return;

                    faction.Leader = nextCandidate;
                    TextObject refusal = new TextObject("{=BC_Ideology_PlayerLeader_Refused}Having declined leadership of the {FACTION_NAME}, you leave {CLAN_NAME} to represent its interests in court.");
                    refusal.SetTextVariable("FACTION_NAME", GetFactionDisplayName(faction));
                    refusal.SetTextVariable("CLAN_NAME", nextCandidate.Name);
                    BellumCivileNotifications.Show(
                        refusal,
                        BellumNotificationColors.Politics,
                        primaryKingdom: kingdom,
                        primaryClan: nextCandidate);
                }), true)

(new MultiSelectionInquiryData(
                Text("BC_Lordship_ReplacementTitle", "Appoint a New Commander").ToString(),
                Text("BC_Lordship_ReplacementBody", "{HERO} must relinquish command of {PARTY}. Choose a new commander to keep the party in the field, or order it disbanded.")
                    .SetTextVariable("HERO", former.Name).SetTextVariable("PARTY", party.Name).ToString(), choices, true, 1, 1,
                Text("BC_Lordship_ReplacementAppoint", "Appoint").ToString(), Text("BC_Lordship_ReplacementDisband", "Disband Party").ToString(),
                selected =>
                {
                    if (selected?.FirstOrDefault()?.Identifier is Hero replacement) Decide(replacement);
                    else { _replacementInquiryOpen = false; _retirementQueued = true; }
                }, _ => Decide(null)), true)

(new MultiSelectionInquiryData(
                Text("BC_Indenture_Renew", "Renew Indenture").ToString(),
                Text("BC_Indenture_RenewalTerms", "{HERO} offers to serve for another term, with the fee payable in advance.")
                    .SetTextVariable("HERO", contract.Holder.Name).ToString(), choices, true, 1, 1,
                Text("BC_Indenture_Agree", "Agree").ToString(), Text("BC_UI_Cancel", "Cancel").ToString(), selected =>
                {
                    _indentureInquiryOpen = false;
                    if (!(selected?.FirstOrDefault()?.Identifier is int years)) return;
                    if (!TrySignIndenture(contract.Holder, years, out var reason, expectedEnd))
                        InformationManager.DisplayMessage(new InformationMessage(reason.ToString(), Colors.Red));
                    else InformationManager.DisplayMessage(new InformationMessage(Text("BC_Indenture_Renewed", "Your indenture with {HERO} has been renewed.")
                        .SetTextVariable("HERO", contract.Holder.Name).ToString()));
                }, _ => _indentureInquiryOpen = false), true)

(new MultiSelectionInquiryData(
                Label("{=BC_Challenge_Title}Dynastic Falling-out"), text + "\n\n" + PowerSummary(record)
                    + "\n\n" + DemandEstatePreview(record), choices, false, 1, 1,
                Label("{=BC_Challenge_Confirm}Confirm response"), "",
                selected =>
                {
                    _inquiry = null;
                    if (selected == null || selected.Count != 1 || !(selected[0].Identifier is SuccessionChallengePhase phase)) return;
                    if (!RecordPlayerResponse(record, phase))
                        InformationManager.DisplayMessage(new InformationMessage(Label("{=BC_Challenge_Changed}The challenge conditions changed. No response was recorded.")));
                }, null), true)

(new MultiSelectionInquiryData(
                    new TextObject("{=BC_VoluntaryPact_ChooseHostageTitle}A Pledge of Peace").ToString(), body.ToString(), choices,
                    false, 1, 1, new TextObject("{=BC_VoluntaryPact_ConfirmChoice}Confirm").ToString(), null,
                    selected =>
                    {
                        _targetInquiryOpen = false;
                        if (selected?.Count != 1 || !IsPlayerRulingHouse(proposal)
                            || proposal.Phase != VoluntaryPactProposalPhase.TargetChoice) return;
                        if (!(selected[0].Identifier is Hero hostage)) { CancelProposal(proposal, VoluntaryPactCloseReason.TargetDeclined); return; }
                        ApplyPlayerTargetChoice(proposal, hostage);
                    }, null), true)

(new InquiryData(new TextObject("{=BC_FeudLeave_Title}Withdraw Your Pledge").ToString(),
                    text.ToString(), true, true, new TextObject("{=BC_UI_Leave}Leave").ToString(),
                    new TextObject("{=BC_FeudLeave_Remain}Remain").ToString(), () =>
                    {
                        bool success = behavior.TryWithdrawPlayerSupport(feud.RecordId, out var reason);
                        BellumCivileNotifications.ShowPersonal(success
                            ? new TextObject("{=BC_FeudLeave_Done}Your house has withdrawn its swords from the feud. Your former allies will remember your broken pledge.")
                            : reason, BellumNotificationColors.Warning);
                        OnClaimFeudActionCompleted();
                        RefreshButtonStates();
                    }, null), true)

(new InquiryData(RenounceText, description.ToString(), true, true,
                new TextObject("{=BC_Renounce_Accept}Renounce Claim").ToString(),
                new TextObject("{=BC_UI_Cancel}Cancel").ToString(), () =>
                {
                    if (!FeudalTitlePlayerActionService.TryExecuteRenunciation(Title, out var reason))
                    {
                        ShowActionFailure(reason?.ToString());
                        RefreshPlayerActions();
                        return;
                    }
                    var message = new TextObject("{=BC_Renounce_Success}Your house has relinquished its claims to {TITLE_NAME}.");
                    message.SetTextVariable("TITLE_NAME", new TextObject("{=!}" + FormatTitleName(Title)));
                    InformationManager.DisplayMessage(new InformationMessage(message.ToString(), Colors.Green));
                    RefreshPlayerActions();
                    _onHierarchyChanged?.Invoke(Title?.TitleId);
                }, null), true)

(new InquiryData(ChallengeText,
                new TextObject("{=BC_PlayerChallenge_Confirm}Call upon the houses of the realm to support your claim to the crown? Once their answers arrive, you may send an ultimatum or withdraw, even if outmatched. Your coalition must hold a town or castle. Failure or withdrawal will delay another challenge.").ToString(),
                true, true, ChallengeText, new TextObject("{=BC_PlayerChallenge_Cancel}Cancel").ToString(),
                () =>
                {
                    SuccessionChallengeBehavior.Instance?.StartPlayerChallenge(Title);
                    RefreshPlayerActions();
                }, null), true)

(new TextInquiryData(
                new TextObject("{=BC_Hierarchy_FormNameTitle}Name the New Title").ToString(),
                description.ToString(),
                true,
                true,
                new TextObject("{=BC_UI_Continue}Continue").ToString(),
                new TextObject("{=BC_UI_Cancel}Cancel").ToString(),
                enteredName =>
                {
                    if (!behavior.TryBuildFormationCandidate(
                        Clan.PlayerClan,
                        targetType,
                        childTitleIds,
                        Title.TitleId,
                        enteredName,
                        allowReorganization: true,
                        out FeudalTitleFormationCandidate candidate,
                        out string buildReason))
                    {
                        ShowActionFailure(buildReason);
                        return;
                    }

                    ShowFormationConfirmation(candidate);
                },
                null,
                false,
                enteredName =>
                {
                    bool valid = FeudalTitleBehavior.IsValidCustomTitleName(enteredName, out _);
                    string validationText = valid
                        ? string.Empty
                        : new TextObject("{=BC_Hierarchy_FormNameInvalid}Enter a name of no more than 64 characters without braces or line breaks.").ToString();
                    return new Tuple<bool, string>(valid, validationText);
                },
                string.Empty,
                defaultName), true)

(new MultiSelectionInquiryData(
                new TextObject("{=BC_Parley_HostageTitle}A Pledge of Peace").ToString(),
                new TextObject("{=BC_Parley_HostageChoose}Which relative shall stand hostage for {DAYS} days? They remain a member of their own house. A voluntary offering earns half its value in treaty credit, subject to the shared offering limit.")
                    .SetTextVariable("DAYS", durationDays).ToString(),
                choices, true, 1, 1, new TextObject("{=BC_UI_Continue}Continue").ToString(), new TextObject("{=BC_UI_Cancel}Cancel").ToString(),
                selected =>
                {
                    if (_proposal != proposal || proposal.DraftRevision != draftRevision || IsDraftEditingDisabled) return;
                    var candidate = TreatyHostageTerms.Available(supplier, receiver, durationDays)
                        .FirstOrDefault(c => c.Hero.StringId == selected?.FirstOrDefault()?.Identifier as string);
                    if (candidate == null)
                    {
                        DisplayActionFailure("the selected relative is no longer available as a hostage");
                        return;
                    }
                    var updated = GetEditableDemandTerms();
                    updated.RemoveAll(t => t.Type == TreatyTermType.HostagePeace && t.FromKingdomId == supplier.StringId);
                    updated.Add(TreatyHostageTerms.Create(supplier, receiver, candidate, offering, durationDays, durationPriced, baselineDays));
                    ReplaceDraft(updated);
                }, null), true)
